import math

def check_condition(n):
    """
    Checks if for all k such that gcd(k, n) = 1, we have k^2 == 1 (mod n).
    """
    if n < 2:
        return False # Constraint n >= 2

    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check k^2 == 1 (mod n)
            if (k * k) % n != 1:
                # Found a counterexample
                return False
    # If loop finishes, the condition holds for all k
    return True

solutions = []
for n in range(2, 13):
    if check_condition(n):
        solutions.append(n)

print("Solutions found for n=2 to n=12:", solutions)
